#include <zephyr/drivers/gpio.h>
#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define GPIO_TEST_PORT_NODE DT_NODELABEL(gpio_test_port)

#if !DT_NODE_HAS_STATUS(GPIO_TEST_PORT_NODE, okay)
#error "GPIO_TEST_PORT_NODE is not defined or not enabled in the devicetree"
#endif

static const struct gpio_dt_spec gpio_test_pin = GPIO_DT_SPEC_GET(GPIO_TEST_PORT_NODE, gpios);

static void gpio_get_direction_setup(void)
{
	if (!device_is_ready(gpio_test_pin.port)) {
		FAIL("GPIO device %s is not ready", gpio_test_pin.port->name);
	}

	int ret = gpio_pin_configure_dt(&gpio_test_pin, GPIO_INPUT);
	zassert_equal(ret, 0, "Failed to configure GPIO pin as input");
}

ZTEST(gpio_get_direction, test_gpio_get_direction)
{
	enum gpio_direction dir;
	int ret;

	/* Test with input pin */
	ret = gpio_get_direction(gpio_test_pin.port, gpio_test_pin.pin, &dir);
	zassert_equal(ret, 0, "Failed to get direction for input pin");
	zassert_equal(dir, GPIO_DIRECTION_IN, "Direction for input pin is incorrect");

	/* Configure as output */
	ret = gpio_pin_configure_dt(&gpio_test_pin, GPIO_OUTPUT);
	zassert_equal(ret, 0, "Failed to configure GPIO pin as output");

	/* Test with output pin */
	ret = gpio_get_direction(gpio_test_pin.port, gpio_test_pin.pin, &dir);
	zassert_equal(ret, 0, "Failed to get direction for output pin");
	zassert_equal(dir, GPIO_DIRECTION_OUT, "Direction for output pin is incorrect");
}

ZTEST_SUITE(gpio_get_direction, NULL, gpio_get_direction_setup, NULL, NULL, NULL);
